<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chi tiết tài khoản</title><link rel="stylesheet" href="/css/professional-form.css"><style>body{margin:0;background:#E9EAE8;font-family:'Times New Roman',Times,serif}.panel{max-width:760px;margin:30px auto;background:#fff;border:1px solid #d6d8d6;border-top:5px solid #b91c1c;border-radius:12px;padding:24px}.panel h1{color:#a31515}.grid{display:grid;grid-template-columns:180px 1fr;border-top:1px solid #e1e3e1}.grid div{padding:12px;border-bottom:1px solid #e1e3e1}.grid div:nth-child(odd){font-weight:700;background:#f7f8f7}.actions{margin-top:16px}.actions a{display:inline-block;background:#a31515;color:#fff;text-decoration:none;padding:10px 14px;border-radius:7px;font-weight:700}</style></head><body><section class="panel"><h1>Chi tiết tài khoản</h1><div class="grid"><div>Họ tên</div><div><?php echo e($taiKhoan['ho_ten']); ?></div><div>Số định danh</div><div><?php echo e($taiKhoan['so_dinh_danh']); ?></div><div>Email</div><div><?php echo e($taiKhoan['email'] ?? 'Chưa cập nhật'); ?></div><div>Số điện thoại</div><div><?php echo e($taiKhoan['so_dien_thoai'] ?? 'Chưa cập nhật'); ?></div><div>Vai trò</div><div><?php echo e($taiKhoan['ten_vai_tro']); ?></div><div>Trạng thái</div><div><?php echo $taiKhoan['trang_thai']==='hoat_dong'?'Hoạt động':'Bị khóa'; ?></div><div>Ngày tạo</div><div><?php echo e($taiKhoan['ngay_tao'] ?? ''); ?></div></div><div class="actions"><a href="/quan_tri/tai_khoan">Quay lại danh sách</a></div></section></body></html>
